<?php require dirname(__DIR__).'/inc/page_helpers.php';admin_required();$stats=[];foreach(['users','games','catalog_items','moderation_reports','forum_topics'] as $table){$stats[$table]=(int)$db->query("SELECT COUNT(*) FROM {$table}")->fetchColumn();}$pending=(int)$db->query("SELECT COUNT(*) FROM moderation_reports WHERE status='pending'")->fetchColumn();page_start('Administration');?><section class="Panel"><h1>Administration</h1><div class="tile-grid"><?php foreach($stats as $name=>$count):?><article class="tile"><b><?=e(ucwords(str_replace('_',' ',$name)))?></b><h2><?=$count?></h2></article><?php endforeach;?></div><p><a href="/Admin/Users.php">Manage users</a> · <a href="/Admin/Catalog.php">Manage catalog</a> · <a href="/Admin/Games.php">Manage places</a> · <a href="/Admin/Reports.php">Reports (<?=$pending?> pending)</a> · <a href="/Admin/Currency.php">Currency tools</a></p></section><?php page_end();?>